CustomCSS:
@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800&display=swap');

html:not(.dark) {
  --background-primary: #FFF8F0;
  --background-secondary: #F5EDE0;
  --theme-primary: #FFF8F0;
  --theme-secondary: #F5EDE0;
  --text-primary: #2C3E50;
  --text-color: #2C3E50;
}

html.dark {
  --background-primary: #1a1410;
  --background-secondary: #2a2018;
  --theme-primary: #1a1410;
  --theme-secondary: #2a2018;
  --text-primary: #F5EDE0;
  --text-color: #F5EDE0;
}

html.transparencyEffects:not(.dark) {
  --background-primary: rgba(255, 248, 240, 0.7);
  --background-secondary: rgba(245, 237, 224, 0.7);
}

:root {
  --beach-sky-top: #87CEEB;
  --beach-sky-bottom: #E8F4FD;
  --beach-sun: #FFD700;
  --beach-sun-glow: #FFA500;
  --beach-sand: #F4D03F;
  --beach-sand-dark: #E8C563;
  --beach-sand-light: #FDEBD0;
  --beach-ocean: #5DADE2;
  --beach-ocean-dark: #3498DB;
  --beach-palm: #27AE60;
  --beach-palm-dark: #1E8449;
  --beach-driftwood: #D4A574;
  --beach-coral: var(--better-main);
  --beach-wave: rgba(255, 255, 255, 0.1);
}

html:not(.dark) body {
  font-family: 'Nunito', system-ui, sans-serif !important;
}

@keyframes sun-pulse {
  0%, 100% { transform: scale(1); opacity: 0.9; }
  50% { transform: scale(1.08); opacity: 1; }
}

@keyframes sun-glow {
  0%, 100% { box-shadow: 0 0 30px 10px rgba(255, 215, 0, 0.3), 0 0 60px 20px rgba(255, 165, 0, 0.15); }
  50% { box-shadow: 0 0 40px 15px rgba(255, 215, 0, 0.4), 0 0 80px 30px rgba(255, 165, 0, 0.2); }
}

@keyframes clouds-move {
  0% { background-position: -250px 18%, -350px 40%, -180px 55%; }
  100% { background-position: calc(100% + 250px) 18%, calc(100% + 350px) 40%, calc(100% + 180px) 55%; }
}

@keyframes clouds-move-slow {
  0% { background-position: -200px 25%, -300px 50%; }
  100% { background-position: calc(100% + 200px) 25%, calc(100% + 300px) 50%; }
}

@keyframes seagulls-fly {
  0% { background-position: -80px 20%, -120px 35%; }
  15% { background-position: 15% 15%, -60px 35%; }
  30% { background-position: 30% 22%, 20% 30%; }
  45% { background-position: 45% 18%, 40% 36%; }
  60% { background-position: 60% 24%, 60% 28%; }
  75% { background-position: 75% 17%, 75% 33%; }
  90% { background-position: 90% 22%, 90% 30%; }
  100% { background-position: calc(100% + 80px) 20%, calc(100% + 120px) 35%; }
}

@keyframes sand-rise {
  0% { height: 0; opacity: 0; }
  100% { height: 12px; opacity: 1; }
}

@keyframes palm-slide {
  0% { transform: translateX(80px) rotate(15deg); opacity: 0; }
  100% { transform: translateX(0) rotate(15deg); opacity: 1; }
}

@keyframes wave-move {
  0% { background-position-x: 0; }
  100% { background-position-x: 40px; }
}

@keyframes shimmer {
  0% { background-position: -200% center; }
  100% { background-position: 200% center; }
}

#title {
  position: relative;
  overflow: visible;
  background: linear-gradient(180deg, var(--beach-sky-top), var(--beach-sky-bottom)) !important;
  color: var(--text-primary) !important;
  border-bottom: 2px solid var(--beach-driftwood) !important;
  box-shadow: 0 2px 15px rgba(135, 206, 235, 0.3) !important;
  z-index: 21 !important;
}

#title::before {
  content: '';
  position: absolute;
  top: 2px;
  right: 15px;
  width: 32px;
  height: 32px;
  background: radial-gradient(circle at 40% 35%, var(--beach-sun), var(--beach-sun-glow) 60%, transparent 72%);
  border-radius: 50%;
  z-index: -1;
  pointer-events: none;
  animation: sun-pulse 3s ease-in-out infinite, sun-glow 3s ease-in-out infinite;
}

#title::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    url('data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%20100%20100'%3E%0A%20%20%3Cpath%20d%3D'M50%208%20L58%2040%20L92%2040%20L65%2058%20L75%2092%20L50%2070%20L25%2092%20L35%2058%20L8%2040%20L42%2040%20Z'%20fill%3D'rgba(240%2C131%2C47%2C0.7)'%20stroke%3D'rgba(200%2C100%2C30%2C0.8)'%20stroke-width%3D'2.5'%20stroke-linejoin%3D'round'%2F%3E%0A%20%20%3Cpath%20d%3D'M50%2018%20L55%2040%20L75%2040%20L60%2052%20L66%2076%20L50%2060%20L34%2076%20L40%2052%20L25%2040%20L45%2040%20Z'%20fill%3D'rgba(245%2C157%2C61%2C0.5)'%2F%3E%0A%20%20%3Ccircle%20cx%3D'50'%20cy%3D'52'%20r%3D'3'%20fill%3D'rgba(200%2C100%2C30%2C0.6)'%2F%3E%0A%3C%2Fsvg%3E'),
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 110 40%27 fill=%27white%27 opacity=%270.7%27%3E%3Cellipse cx=%2740%27 cy=%2728%27 rx=%2730%27 ry=%2714%27/%3E%3Cellipse cx=%2765%27 cy=%2723%27 rx=%2725%27 ry=%2712%27/%3E%3Cellipse cx=%2785%27 cy=%2726%27 rx=%2720%27 ry=%2710%27/%3E%3Crect x=%2722%27 y=%2724%27 width=%2775%27 height=%2715%27 rx=%278%27/%3E%3C/svg%3E'),
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 80 30%27 fill=%27white%27 opacity=%270.6%27%3E%3Cellipse cx=%2730%27 cy=%2720%27 rx=%2722%27 ry=%2710%27/%3E%3Cellipse cx=%2748%27 cy=%2717%27 rx=%2718%27 ry=%279%27/%3E%3Cellipse cx=%2762%27 cy=%2719%27 rx=%2714%27 ry=%277%27/%3E%3Crect x=%2716%27 y=%2718%27 width=%2755%27 height=%2712%27 rx=%276%27/%3E%3C/svg%3E');
  background-repeat: no-repeat, no-repeat, no-repeat;
  background-size: 180px auto, 120px auto, 80px auto;
  animation: clouds-move 28s linear infinite;
}

#container {
  position: relative;
  isolation: isolate;
  background: var(--background-primary) !important;
}

#container #content::before {
  display: none !important;
}

#container::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 140 50%27 fill=%27white%27 opacity=%270.5%27%3E%3Cellipse cx=%2750%27 cy=%2735%27 rx=%2738%27 ry=%2718%27/%3E%3Cellipse cx=%2780%27 cy=%2730%27 rx=%2730%27 ry=%2715%27/%3E%3Cellipse cx=%27105%27 cy=%2733%27 rx=%2724%27 ry=%2712%27/%3E%3Crect x=%2730%27 y=%2731%27 width=%2795%27 height=%2718%27 rx=%279%27/%3E%3C/svg%3E'),
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 38%27 fill=%27white%27 opacity=%270.4%27%3E%3Cellipse cx=%2736%27 cy=%2726%27 rx=%2728%27 ry=%2713%27/%3E%3Cellipse cx=%2758%27 cy=%2722%27 rx=%2722%27 ry=%2711%27/%3E%3Cellipse cx=%2775%27 cy=%2725%27 rx=%2718%27 ry=%279%27/%3E%3Crect x=%2720%27 y=%2723%27 width=%2770%27 height=%2714%27 rx=%277%27/%3E%3C/svg%3E');
  background-repeat: no-repeat, no-repeat;
  background-position: -200px 120px, -300px 180px;
  background-size: 200px auto, 140px auto;
  animation: clouds-move-slow 40s linear infinite;
}

#container::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 50 22%27 fill=%27none%27 stroke=%27rgb(44,62,80)%27 stroke-width=%271.8%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27%3E%3Cpath d=%27M3 18 Q12 3 25 9 Q38 3 47 18%27/%3E%3C/svg%3E'),
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 40 18%27 fill=%27none%27 stroke=%27rgb(44,62,80)%27 stroke-width=%271.5%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27%3E%3Cpath d=%27M2 14 Q10 2 20 7 Q30 2 38 14%27/%3E%3C/svg%3E');
  background-repeat: no-repeat, no-repeat;
  background-size: 60px auto, 45px auto;
  animation: seagulls-fly 18s ease-in-out infinite;
  opacity: 0.8;
}

#menu, #main {
  position: relative;
  z-index: 1;
}

#menu {   background: linear-gradient(180deg, var(--beach-sand-light), var(--background-secondary)) !important;   border-right: 2px solid var(--beach-driftwood) !important;   box-shadow: 4px 0 20px rgba(212, 165, 116, 0.15) !important;   overflow-y: auto !important; }

#menu > ul > li:not(.hasChildren), #menu section {
  transition: background-color 0.3s ease, transform 0.2s ease !important;
  position: relative;
  overflow: hidden;
  border-radius: 8px !important;
  margin: 2px 6px !important;
}

#menu .sub li {
  margin: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

#menu > ul > li:not(.hasChildren):hover, #menu section:hover {
  background: color-mix(in srgb, var(--beach-driftwood) 18%, transparent) !important;
}

#menu > ul > li:not(.hasChildren).active, #menu section.active {
  background: color-mix(in srgb, var(--beach-coral) 20%, transparent) !important;
  box-shadow: inset 3px 0 0 var(--beach-coral), 0 2px 10px color-mix(in srgb, var(--beach-coral) 15%, transparent) !important;
}

#menu > ul > li:not(.hasChildren).active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 0;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(180deg, var(--beach-sand), var(--beach-sand-dark));
  border-radius: 0 0 8px 8px;
  animation: sand-rise 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

#menu > ul > li:not(.hasChildren).active::before {
  content: '';
  position: absolute;
  bottom: 2px;
  right: 2px;
  width: 45px;
  height: 55px;
  z-index: -1;
  pointer-events: none;
  background-image: url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 55 80%27%3E%3Cpath d=%27M26 80 Q24 60 22 40 Q21 28 25 18%27 stroke=%27rgb(139,105,20)%27 stroke-width=%274%27 fill=%27none%27/%3E%3Cpath d=%27M26 18 Q8 8 2 20 Q10 14 18 16 Z%27 fill=%27rgb(46,204,113)%27/%3E%3Cpath d=%27M26 18 Q12 2 4 6 Q10 8 18 13 Z%27 fill=%27rgb(39,174,96)%27/%3E%3Cpath d=%27M26 18 Q40 2 48 8 Q40 10 34 15 Z%27 fill=%27rgb(46,204,113)%27/%3E%3Cpath d=%27M26 18 Q44 10 50 18 Q42 14 34 16 Z%27 fill=%27rgb(39,174,96)%27/%3E%3Ccircle cx=%2726%27 cy=%2719%27 r=%272.5%27 fill=%27rgb(139,69,19)%27/%3E%3Ccircle cx=%2723%27 cy=%2722%27 r=%272%27 fill=%27rgb(160,82,45)%27/%3E%3C/svg%3E');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: bottom center;
  animation: palm-slide 0.7s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

#menu ul::before {
  background-color: transparent !important;
}

#content {
  background: transparent !important;
}

#main {
  background: var(--background-primary) !important;
  border-radius: 12px 0 0 0 !important;
}

#main > .dashboard {
  gap: 16px !important;
}

#main > .dashboard section,
.dashlet,
.notice,
.document {
  position: relative;
  background: linear-gradient(165deg, var(--background-primary), var(--background-secondary)) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 30%, transparent) !important;
  border-radius: 14px !important;
  box-shadow: 0 4px 16px rgba(212, 165, 116, 0.12), 0 1px 3px rgba(0, 0, 0, 0.04) !important;
  transition: transform 0.25s ease, box-shadow 0.25s ease !important;
}

#main > .dashboard section:hover,
.dashlet:hover,
.notice:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(212, 165, 116, 0.18), 0 2px 6px rgba(0, 0, 0, 0.06) !important;
}

#main > .dashboard section::before,
.dashlet::before,
.notice::before,
.document::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  border-radius: 14px 0 0 14px;
  background: linear-gradient(180deg, var(--beach-coral), var(--beach-ocean));
  box-shadow: 0 0 12px color-mix(in srgb, var(--beach-coral) 30%, transparent);
  pointer-events: none;
}

#container #content #title {
  background-color: transparent !important;
  box-shadow: none !important;
  border-bottom: none !important;
}

#main #home-container .shortcut-container div,
.shortcut {
  background: linear-gradient(135deg, var(--background-primary), var(--background-secondary)) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 25%, transparent) !important;
  border-radius: 12px !important;
  box-shadow: 0 2px 8px rgba(212, 165, 116, 0.1) !important;
  transition: transform 0.2s ease, box-shadow 0.2s ease !important;
}

.shortcut:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 6px 20px rgba(212, 165, 116, 0.18) !important;
}

.day {
  background: linear-gradient(180deg, var(--background-primary), var(--background-secondary)) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 25%, transparent) !important;
  border-radius: 12px !important;
  box-shadow: 0 2px 8px rgba(212, 165, 116, 0.08) !important;
  position: relative;
  overflow: hidden;
}

.day::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: repeating-linear-gradient(90deg, var(--beach-ocean) 0px, var(--beach-ocean) 8px, transparent 8px, transparent 12px);
  background-size: 40px 3px;
  animation: wave-move 3s linear infinite;
  pointer-events: none;
  opacity: 0.5;
}

.day h4 {
  font-size: 11px !important;
}

.dashboard > div,
.dashboard > .message {
  background: linear-gradient(165deg, var(--background-primary), var(--background-secondary)) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 28%, transparent) !important;
  border-radius: 14px !important;
  box-shadow: 0 4px 16px rgba(212, 165, 116, 0.12) !important;
}

.upcoming-items {
  background: color-mix(in srgb, var(--beach-sand-light) 40%, transparent) !important;
  border-radius: 8px !important;
}

.entriesWrapper {
  background: var(--background-primary) !important;
  border-radius: 8px !important;
}

table tbody tr td {
  border-color: color-mix(in srgb, var(--beach-driftwood) 15%, transparent) !important;
}

table tbody tr:nth-child(even) td {
  background: color-mix(in srgb, var(--beach-sand-light) 25%, var(--background-primary)) !important;
}

table tbody tr:hover td {
  background: color-mix(in srgb, var(--beach-coral) 8%, var(--background-primary)) !important;
}

a {
  color: var(--beach-coral) !important;
  transition: color 0.2s ease, text-shadow 0.2s ease !important;
}

a:hover {
  color: color-mix(in srgb, var(--beach-coral) 80%, white) !important;
  text-shadow: 0 0 8px color-mix(in srgb, var(--beach-coral) 25%, transparent);
}

.legacy-root button,
.legacy-root a,
.uiButton,
.addedButton,
[class*="uiButton"] {
  background: linear-gradient(180deg, var(--background-primary), var(--background-secondary)) !important;
  border: 1px solid color-mix(in srgb, var(--beach-ocean) 40%, transparent) !important;
  border-radius: 10px !important;
  color: var(--text-primary) !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04) !important;
  transition: all 0.2s ease !important;
}

.legacy-root button:hover,
.legacy-root a:hover,
.uiButton:hover,
.addedButton:hover {
  background: color-mix(in srgb, var(--beach-ocean) 12%, var(--background-primary)) !important;
  border-color: var(--beach-ocean) !important;
  box-shadow: 0 4px 12px color-mix(in srgb, var(--beach-ocean) 20%, transparent) !important;
  transform: translateY(-1px);
}

.MessageList__MessageList___3DxoC {
  background: var(--background-primary) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 20%, transparent) !important;
  border-radius: 12px !important;
  box-shadow: 0 2px 10px rgba(212, 165, 116, 0.1) !important;
}

.Message__Message___3oJaU {
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 20%, transparent) !important;
  background: var(--background-primary) !important;
  border-radius: 10px !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.03) !important;
}

.Message__Message___3oJaU .userHTML {
  background: var(--background-primary) !important;
}

.Viewer__organisation___2eDrr {
  border-right: 1px solid color-mix(in srgb, var(--beach-driftwood) 25%, transparent) !important;
}

.notifications__bubble___1EkSQ {
  background: var(--background-primary) !important;
  box-shadow: 0 2px 8px color-mix(in srgb, var(--beach-coral) 25%, transparent) !important;
  border: 1px solid var(--beach-coral) !important;
}

.LabelList__LabelList___2RJFf > li.LabelList__selected___3Egk7 {
  background: var(--background-primary) !important;
  border: 1px solid var(--beach-coral) !important;
  border-radius: 8px !important;
  box-shadow: 0 0 6px color-mix(in srgb, var(--beach-coral) 20%, transparent) !important;
}

#container #content .buttonChecklist,
#container #content .search {
  border-radius: 8px !important;
  background-color: var(--background-primary) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 20%, transparent) !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04) inset !important;
}

#container #content .buttonChecklist {
  transform: scale(1.08);
  margin: 0 12px 4px 4px !important;
}

.mediaWrapper,
.mediaRecorder,
.MediaRecorder__MediaRecorder___2c2_M,
.MediaRecorder__actions___3Jjvp,
.pane.tall .footer,
.anyoneSelect,
.pane.tall .header {
  background: transparent !important;
}

.pane.tall {
  background: var(--background-primary) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 25%, transparent) !important;
  border-radius: 12px !important;
}

.cke_button.cke_button_on {
  background: color-mix(in srgb, var(--beach-coral) 15%, var(--background-primary)) !important;
}

.documents td.colourBar {
  color: var(--beach-coral) !important;
  font-size: small;
}

tr.document.label-match {
  box-shadow: 0 0 4px color-mix(in srgb, var(--beach-coral) 25%, transparent) !important;
}

.userInfohouse {
  border: 1px solid var(--beach-driftwood) !important;
}

.userInfosvgdiv svg path {
  filter: drop-shadow(0 0 2px var(--beach-coral));
}

#loading > div {
  color: var(--beach-coral);
}

#loading {
  background: var(--background-primary) !important;
}

#loading::before {
  content: '';
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 80px;
  height: 80px;
  background: radial-gradient(circle, var(--beach-sun) 0%, transparent 70%);
  border-radius: 50%;
  animation: sun-pulse 1.5s ease-in-out infinite;
  pointer-events: none;
}

audio {
  filter: sepia(0.3) hue-rotate(320deg);
}

.uiFileHandlerPanel,
.formattedText > .wrapper > .cke > .cke_inner > .cke_contents {
  background: var(--background-primary) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 25%, transparent) !important;
  border-radius: 8px !important;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: var(--background-secondary);
  border-radius: 5px;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--beach-driftwood), var(--beach-sand-dark));
  border-radius: 5px;
  border: 2px solid var(--background-secondary);
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, var(--beach-sand-dark), var(--beach-driftwood));
}

#content #main #news-container h1,
#home-container > div {
  background: var(--background-primary) !important;
  border: 1px solid color-mix(in srgb, var(--beach-driftwood) 25%, transparent) !important;
  border-radius: 12px !important;
  box-shadow: 0 2px 10px rgba(212, 165, 116, 0.1) !important;
}

#menu ul::before {
  border-bottom: none !important;
}

#container {
  border-top-left-radius: 1rem !important;
}

#container #content #main {
  border-top: 2px solid var(--beach-coral) !important;
  border-left: 2px solid color-mix(in srgb, var(--beach-coral) 30%, transparent) !important;
  box-shadow: 3px 3px 8px -5px var(--beach-coral) inset !important;
  border-top-left-radius: 1rem;
  background: transparent;
}

@keyframes wave-slide {
  0% { background-position-x: 0; }
  100% { background-position-x: 200px; }
}

@keyframes starfish-float {
  0%, 100% { transform: translateY(0); opacity: 0.6; }
  50% { transform: translateY(-4px); opacity: 0.85; }
}

#content::after {
  content: '';
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 24px;
  background-image:
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 200 24%27%3E%3Cpath d=%27M0 10 Q25 2 50 10 Q75 18 100 10 Q125 2 150 10 Q175 18 200 10 V24 H0 Z%27 fill=%27rgba(93,173,226,0.5)%27/%3E%3C/svg%3E'),
    url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 160 24%27%3E%3Cpath d=%27M0 16 Q20 8 40 16 Q60 24 80 16 Q100 8 120 16 Q140 24 160 16 V24 H0 Z%27 fill=%27rgba(52,152,219,0.3)%27/%3E%3C/svg%3E');
  background-repeat: repeat-x;
  background-size: 200px 24px, 160px 24px;
  pointer-events: none;
  z-index: 999;
  animation: wave-slide 4s linear infinite;
  opacity: 1;
}

.notice::after,
.document::after {
  content: '';
  position: absolute;
  width: 26px;
  height: 26px;
  background-image: url('data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 100 100%27%3E%3Cpath d=%27M50 8 L58 40 L92 40 L65 58 L75 92 L50 70 L25 92 L35 58 L8 40 L42 40 Z%27 fill=%27rgba(240,131,47,0.7)%27 stroke=%27rgba(200,100,30,0.8)%27 stroke-width=%272.5%27 stroke-linejoin=%27round%27/%3E%3Cpath d=%27M50 18 L55 40 L75 40 L60 52 L66 76 L50 60 L34 76 L40 52 L25 40 L45 40 Z%27 fill=%27rgba(245,157,61,0.5)%27/%3E%3Ccircle cx=%2750%27 cy=%2752%27 r=%273%27 fill=%27rgba(200,100,30,0.6)%27/%3E%3C/svg%3E');
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none;
}

.notice:nth-child(6n+1)::after, .document:nth-child(6n+1)::after {
  bottom: 4px; right: 6px;
  rotate: 15deg;
  animation: starfish-float 4s ease-in-out infinite;
}

.notice:nth-child(6n+2)::after, .document:nth-child(6n+2)::after {
  top: 4px; right: 6px;
  rotate: -25deg;
  animation: starfish-float 4.5s ease-in-out infinite;
}

.notice:nth-child(6n+3)::after, .document:nth-child(6n+3)::after {
  bottom: 4px; left: 6px;
  rotate: 45deg;
  animation: starfish-float 5s ease-in-out infinite;
}

.notice:nth-child(6n+4)::after, .document:nth-child(6n+4)::after {
  top: 4px; left: 6px;
  rotate: -60deg;
  animation: starfish-float 3.8s ease-in-out infinite;
}

.notice:nth-child(6n+5)::after, .document:nth-child(6n+5)::after {
  top: 50%; right: 4px;
  margin-top: -13px;
  rotate: 80deg;
  animation: starfish-float 4.2s ease-in-out infinite;
}

.notice:nth-child(6n)::after, .document:nth-child(6n)::after {
  top: 50%; left: 4px;
  margin-top: -13px;
  rotate: -35deg;
  animation: starfish-float 5.2s ease-in-out infinite;
}

@media (min-width: 1000px) {
  ol > [data-label] {
    border-right-color: transparent !important;
  }
}

@media (max-width: 900px) {
  #title::before {
    width: 22px;
    height: 22px;
    right: 8px;
  }
  #title::after {
    background-size: 120px auto, 80px auto, 0;
  }
}
